from typing import List

def articulationPoints(V: int, adj: List[List[int]]) -> List[int]:
    if V == 1:
        return [-1]

    visited = [False] * V
    disc = [0] * V
    low = [0] * V
    parent = [-1] * V
    is_articulation = [False] * V
    time = 0

    def dfs(u):
        nonlocal time
        children = 0
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if not visited[v]:
                children += 1
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])

                if parent[u] == -1 and children > 1:
                    is_articulation[u] = True
                if parent[u] != -1 and low[v] >= disc[u]:
                    is_articulation[u] = True
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    for u in range(V):
        if not visited[u]:
            dfs(u)

    articulation = [u for u in range(V) if is_articulation[u]]
    if not articulation:
        return [-1]
    return sorted(articulation)
